import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function deleteAuthUserEraseAccount(props: {
  user: UserPayload;
}): Promise<ITodoListUser.IDeletionResult> {
  // Get current timestamp as string for all operations
  const now: string & tags.Format<"date-time"> = toISOStringSafe(new Date());

  // Check the user exists, is not already deleted
  const user = await MyGlobal.prisma.todo_list_users.findFirst({
    where: {
      id: props.user.id,
      is_active: true,
      is_verified: true,
      deleted_at: null,
    },
  });
  if (!user) {
    throw new HttpException("User not found or already deleted.", 404);
  }

  // Transactional, cascading annihilation of all user data
  await MyGlobal.prisma.$transaction([
    // Delete all todos
    MyGlobal.prisma.todo_list_todos.deleteMany({
      where: { todo_list_user_id: props.user.id },
    }),
    // Remove all sessions
    MyGlobal.prisma.todo_list_user_sessions.deleteMany({
      where: { todo_list_user_id: props.user.id },
    }),
    // Delete all verifications
    MyGlobal.prisma.todo_list_user_email_verifications.deleteMany({
      where: { todo_list_user_id: props.user.id },
    }),
    // Delete all password resets
    MyGlobal.prisma.todo_list_user_password_resets.deleteMany({
      where: { todo_list_user_id: props.user.id },
    }),
    // Soft-delete the user entity
    MyGlobal.prisma.todo_list_users.update({
      where: { id: props.user.id },
      data: { is_active: false, deleted_at: now, updated_at: now },
    }),
  ]);

  // All data is now unrecoverably erased
  return { success: true };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function postAuthUserChangePassword(props: {
  user: UserPayload;
  body: ITodoListUser.IChangePassword;
}): Promise<ITodoListUser.IChangePasswordResult> {
  const { user, body } = props;

  // Lookup current user by id, only if active, verified, not deleted
  const existing = await MyGlobal.prisma.todo_list_users.findUnique({
    where: { id: user.id },
  });

  if (
    !existing ||
    existing.is_active !== true ||
    existing.is_verified !== true ||
    existing.deleted_at !== null
  ) {
    return {
      success: false,
      reason: "Account inactive, unverified, or not found.",
    };
  }

  // Securely verify old password
  const passwordOk = await PasswordUtil.verify(
    body.old_password,
    existing.password_hash,
  );
  if (!passwordOk) {
    return {
      success: false,
      reason: "Incorrect current password",
    };
  }

  // Hash new password
  const newHash = await PasswordUtil.hash(body.new_password);
  const updated_at = toISOStringSafe(new Date());
  // Save update atomically
  await MyGlobal.prisma.todo_list_users.update({
    where: { id: user.id },
    data: { password_hash: newHash, updated_at },
  });

  return { success: true };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUserSession";
import { IPageITodoListUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListUserSession";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function patchTodoListUserUsersMeSessions(props: {
  user: UserPayload;
  body: ITodoListUserSession.IRequest;
}): Promise<IPageITodoListUserSession> {
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 100;
  const skip = (page - 1) * limit;
  const orderByField = props.body.order_by ?? "created_at";
  const orderDirection = props.body.order ?? "desc";

  // Safely convert 'from' and 'to' to string (ISO) if present
  const from = props.body.from ? toISOStringSafe(props.body.from) : undefined;
  const to = props.body.to ? toISOStringSafe(props.body.to) : undefined;

  let where: any = {
    todo_list_user_id: props.user.id,
  };
  if (from && to) {
    where.created_at = { gte: from, lte: to };
  } else if (from) {
    where.created_at = { gte: from };
  } else if (to) {
    where.created_at = { lte: to };
  }

  const [sessions, total] = await Promise.all([
    MyGlobal.prisma.todo_list_user_sessions.findMany({
      where: where,
      orderBy: [
        {
          [orderByField]: orderDirection satisfies "asc" | "desc" as
            | "asc"
            | "desc",
        },
        ...(orderByField !== "created_at"
          ? [{ created_at: "desc" as Prisma.SortOrder }]
          : []),
      ],
      skip,
      take: limit,
    }),
    MyGlobal.prisma.todo_list_user_sessions.count({
      where: where,
    }),
  ]);

  return {
    pagination: {
      current: page satisfies number as number,
      limit: limit satisfies number as number,
      records: total satisfies number as number,
      pages: Math.ceil(total / limit) satisfies number as number,
    },
    data: sessions.map((session) => ({
      id: session.id,
      todo_list_user_id: session.todo_list_user_id,
      ip: session.ip,
      href: session.href,
      referrer: session.referrer,
      created_at: toISOStringSafe(session.created_at),
      expired_at:
        session.expired_at === null
          ? null
          : toISOStringSafe(session.expired_at),
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUserEmailVerification } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUserEmailVerification";

export async function postAuthUserVerifyEmail(props: {
  body: ITodoListUserEmailVerification.IVerify;
}): Promise<ITodoListUserEmailVerification.IVerified> {
  const { verification_token } = props.body;

  // Find verification event
  const verification =
    await MyGlobal.prisma.todo_list_user_email_verifications.findUnique({
      where: { verification_token },
    });

  if (!verification) {
    return {
      success: false,
      message:
        "Invalid or unknown verification token. Please check your link or request a new email verification.",
    };
  }

  // Check if already used
  if (verification.consumed_at !== null) {
    return {
      success: false,
      message:
        "This verification token has already been used. Please request a new verification email if needed.",
    };
  }

  // Check expiration
  const now = toISOStringSafe(new Date());
  if (toISOStringSafe(verification.expires_at) <= now) {
    return {
      success: false,
      message:
        "This verification token has expired. Please request a new verification email.",
    };
  }

  // Success path: transactionally consume token & verify user
  await MyGlobal.prisma.$transaction([
    MyGlobal.prisma.todo_list_user_email_verifications.update({
      where: {
        id: verification.id,
      },
      data: {
        consumed_at: now,
      },
    }),
    MyGlobal.prisma.todo_list_users.update({
      where: {
        id: verification.todo_list_user_id,
      },
      data: {
        is_verified: true,
        is_active: true,
        updated_at: now,
      },
    }),
  ]);

  return {
    success: true,
    message:
      "Your email has been verified and your account is now active. You may now log in.",
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function putTodoListUserTodosTodoId(props: {
  user: UserPayload;
  todoId: string & tags.Format<"uuid">;
  body: ITodoListTodo.IUpdate;
}): Promise<ITodoListTodo> {
  const now = toISOStringSafe(new Date());
  // Step 1: fetch todo and validate ownership
  const existing = await MyGlobal.prisma.todo_list_todos.findFirst({
    where: {
      id: props.todoId,
      todo_list_user_id: props.user.id,
      // 'deleted_at' removed, not present in schema
    },
  });
  if (!existing) {
    throw new HttpException("Todo not found or not accessible", 404);
  }
  // Step 2: determine completed_at update (business logic)
  let completed_at: (string & tags.Format<"date-time">) | null | undefined =
    existing.completed_at === null
      ? null
      : toISOStringSafe(existing.completed_at);
  if (Object.prototype.hasOwnProperty.call(props.body, "is_completed")) {
    if (props.body.is_completed === true && existing.is_completed === false) {
      completed_at = now;
    } else if (
      props.body.is_completed === false &&
      existing.is_completed === true
    ) {
      completed_at = null;
    }
  }
  // Step 3: prepare update fields
  const updateData: { [key: string]: unknown } = {
    updated_at: now,
  };
  if (Object.prototype.hasOwnProperty.call(props.body, "title"))
    updateData.title = props.body.title;
  if (Object.prototype.hasOwnProperty.call(props.body, "description"))
    updateData.description = props.body.description;
  if (Object.prototype.hasOwnProperty.call(props.body, "due_date"))
    updateData.due_date = props.body.due_date;
  if (Object.prototype.hasOwnProperty.call(props.body, "is_completed"))
    updateData.is_completed = props.body.is_completed;
  if (Object.prototype.hasOwnProperty.call(props.body, "is_completed"))
    updateData.completed_at = completed_at;
  // Step 4: execute update
  const updated = await MyGlobal.prisma.todo_list_todos.update({
    where: { id: props.todoId },
    data: updateData,
  });
  // Step 5: Construct ITodoListTodo response, enforce DTO types and null/undefined rules
  return {
    id: updated.id,
    todo_list_user_id: updated.todo_list_user_id,
    title: updated.title,
    description: updated.description === null ? undefined : updated.description,
    due_date:
      updated.due_date === null ? undefined : toISOStringSafe(updated.due_date),
    is_completed: updated.is_completed,
    completed_at:
      updated.completed_at === null
        ? undefined
        : toISOStringSafe(updated.completed_at),
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserLogin(props: {
  body: ITodoListUser.ILogin;
}): Promise<ITodoListUser.IAuthorized> {
  const user = await MyGlobal.prisma.todo_list_users.findFirst({
    where: {
      email: props.body.email.toLowerCase(),
    },
  });
  if (!user || !user.is_active || !user.is_verified) {
    throw new HttpException("Invalid credentials", 401);
  }
  const valid = await PasswordUtil.verify(
    props.body.password,
    user.password_hash,
  );
  if (!valid) {
    throw new HttpException("Invalid credentials", 401);
  }
  const now = new Date();
  const accessExpiresDate = new Date(now.getTime() + 60 * 60 * 1000);
  const refreshExpiresDate = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
  const sessionId = v4();

  await MyGlobal.prisma.todo_list_user_sessions.create({
    data: {
      id: sessionId,
      todo_list_user_id: user.id,
      ip:
        typeof props.body.ip === "string"
          ? (props.body.ip satisfies string as string)
          : "",
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: toISOStringSafe(now),
      expired_at: toISOStringSafe(accessExpiresDate),
    },
  });

  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "user",
        id: user.id,
        session_id: sessionId,
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "user",
        id: user.id,
        session_id: sessionId,
        tokenType: "refresh",
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpiresDate),
    refreshable_until: toISOStringSafe(refreshExpiresDate),
  };

  return {
    id: user.id,
    email: user.email,
    display_name: user.display_name,
    is_verified: user.is_verified,
    is_active: user.is_active,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    deleted_at: user.deleted_at ? toISOStringSafe(user.deleted_at) : undefined,
    token,
    user: undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserRefresh(props: {
  body: ITodoListUser.IRefresh;
}): Promise<ITodoListUser.IAuthorized> {
  let decoded: { id: string; session_id: string; type: "user" };
  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as { id: string; session_id: string; type: "user" };
  } catch {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  if (decoded.type !== "user") {
    throw new HttpException("Invalid token type", 403);
  }

  // Check for valid session and user
  const session = await MyGlobal.prisma.todo_list_user_sessions.findFirst({
    where: {
      id: decoded.session_id,
      todo_list_user_id: decoded.id,
    },
    include: {
      user: true,
    },
  });
  if (!session) {
    throw new HttpException("Session not found or revoked", 401);
  }
  // expired_at is null or in the future
  if (
    session.expired_at !== null &&
    new Date(session.expired_at).getTime() <= Date.now()
  ) {
    throw new HttpException("Session has expired", 401);
  }
  const user = session.user;
  if (!user || user.deleted_at !== null) {
    throw new HttpException("User account deleted", 403);
  }
  if (!user.is_active) {
    throw new HttpException("User account is inactive", 403);
  }

  // Generate times in ISO string format (not using Date type in domain)
  const now = new Date();
  const accessExpiresAtStr = toISOStringSafe(
    new Date(now.getTime() + 60 * 60 * 1000),
  );
  const refreshExpiresAtStr = toISOStringSafe(
    new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000),
  );

  const accessToken = jwt.sign(
    {
      type: "user",
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: toISOStringSafe(now),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: "user",
      id: decoded.id,
      session_id: decoded.session_id,
      tokenType: "refresh",
      created_at: toISOStringSafe(now),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  // Update session expiration in DB
  await MyGlobal.prisma.todo_list_user_sessions.update({
    where: { id: decoded.session_id },
    data: {
      expired_at: refreshExpiresAtStr,
    },
  });

  return {
    id: user.id,
    email: user.email,
    display_name: user.display_name,
    is_verified: user.is_verified,
    is_active: user.is_active,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    deleted_at:
      user.deleted_at === null ? null : toISOStringSafe(user.deleted_at),
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: accessExpiresAtStr,
      refreshable_until: refreshExpiresAtStr,
    },
    user: {
      id: user.id,
      email: user.email,
      display_name: user.display_name,
      is_verified: user.is_verified,
      is_active: user.is_active,
      created_at: toISOStringSafe(user.created_at),
      updated_at: toISOStringSafe(user.updated_at),
      deleted_at:
        user.deleted_at === null ? null : toISOStringSafe(user.deleted_at),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUserPasswordReset } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUserPasswordReset";

export async function postAuthUserRequestPasswordReset(props: {
  body: ITodoListUserPasswordReset.IRequest;
}): Promise<ITodoListUserPasswordReset.IRequested> {
  const email = props.body.email.trim().toLowerCase();
  const user = await MyGlobal.prisma.todo_list_users.findUnique({
    where: { email },
  });

  if (user && user.is_active && user.is_verified && user.deleted_at === null) {
    const now = Date.now();
    const nowString = toISOStringSafe(new Date(now));
    const expiresString = toISOStringSafe(new Date(now + 60 * 60 * 1000));

    // Rate limit: allow at most one active (unredeemed, unexpired, recent) request per 15 minutes
    const earliestAllowed = toISOStringSafe(new Date(now - 15 * 60 * 1000));
    const recentReset =
      await MyGlobal.prisma.todo_list_user_password_resets.findFirst({
        where: {
          todo_list_user_id: user.id,
          created_at: { gte: earliestAllowed },
          consumed_at: null,
          expires_at: { gt: nowString },
        },
      });
    if (!recentReset) {
      await MyGlobal.prisma.todo_list_user_password_resets.create({
        data: {
          id: v4(),
          todo_list_user_id: user.id,
          reset_token: v4(),
          consumed_at: null,
          expires_at: expiresString,
          created_at: nowString,
        },
      });
      // In production: trigger external email send with reset_token
    }
  }
  return {
    message:
      "If an account with this email exists, a reset link has been sent.",
  };
}

